  const handleEnviarCobrancaWhatsapp = (fatura) => {
    if (!selectedFaturasCompany) return;
    const rawPhone = selectedFaturasCompany.telefone || '';
    const cleanPhone = rawPhone.replace(/\D/g, '');

    if (!cleanPhone) {
      showToast('Por favor, configure o telefone da empresa na Aba 1.', 'error');
      return;
    }

    const parts = fatura.data_vencimento.split('-');
    const formattedDate = parts.length === 3 ? `${parts[2]}/${parts[1]}/${parts[0]}` : fatura.data_vencimento;
    const formattedValue = parseFloat(fatura.valor_mensalidade).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    const link = fatura.link_pagamento || 'Link/PIX não cadastrado';

    const msg = `Olá, tudo bem?\n\nAqui é da equipe financeira da *House Software*.\n\nPassando para lembrar que a fatura da sua licença do sistema *Zênite* com vencimento em *${formattedDate}* no valor de *${formattedValue}* já está disponível.\n\nPara efetuar o pagamento, utilize o código/link abaixo:\n\n${link}\n\nAgradecemos a parceria! Se tiver qualquer dúvida, estamos à disposição.`;

    const whatsappUrl = `https://wa.me/${cleanPhone}?text=${encodeURIComponent(msg)}`;
    window.open(whatsappUrl, '_blank');
  };

  const baixarMensalidade = async (faturaId) => {
    if (!window.confirm('Confirmar baixa do pagamento desta fatura? O status mudará para PAGO.')) return;

    try {
      const { error } = await supabase
        .from('faturas_saas')
        .update({ status: 'PAGO' })
        .eq('id', faturaId);

      if (error) throw error;

      setCompanyFaturas(prev =>
        prev.map(f => f.id === faturaId ? { ...f, status: 'PAGO' } : f)
      );
      showToast('Mensalidade baixada com sucesso!', 'success');

      // Automatizar a emissão da NFS-e via Webhook
      try {
        const { data: { session: currentSession } } = await supabase.auth.getSession();
        const token = currentSession?.access_token;
        if (token) {
          safeFetchJson('/api/webhooks/faturas-saas', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${token}`
            },
            body: JSON.stringify({ fatura_id: faturaId })
          }).then(res => {
            if (res.ok && res.data?.success) {
              const data = res.data;
              showToast('NFS-e de mensalidade emitida via webhook com sucesso!', 'success');
              setCompanyFaturas(prev =>
                prev.map(f => f.id === faturaId ? { ...f, status: 'PAGO', nfse_id: data.nfse_id, nfse_pdf_url: data.nfse_pdf_url } : f)
              );
            } else if (res.data?.error) {
              console.error('Erro no webhook de fatura SaaS:', res.data.error);
            }
          }).catch(e => console.error('Erro na chamada do webhook de fatura SaaS:', e));
        }
      } catch (webhookErr) {
        console.error('Falha ao acionar webhook:', webhookErr);
      }
    } catch (err) {
      console.error('Erro ao baixar mensalidade:', err);
      showToast('Erro ao confirmar pagamento.', 'error');
    }
  };

  const handleEmitirNfse = async (fatura) => {
    setIsFiscalLoading(true);
    try {
      const result = await emitirNfseStub(selectedFaturasCompany, fatura);

      // 1. Mostrar o alerta com o ID da Nota
      alert(`${result.mensagem}\nNFS-e ID: ${result.nfe_id}`);

      // 2. Abrir o PDF dummy funcional em uma nova aba
      const dummyPdfUrl = 'https://www.w3.org/WAI/ER/tests/xhtml/testfiles/resources/pdf/dummy.pdf';
      window.open(dummyPdfUrl, '_blank');

      // 3. Fazer o download local do comprovante formatado como TXT (representando a nota)
      const element = document.createElement("a");
      const file = new Blob([
        `==================================================\n`,
        `          ZÊNITE OS - NOTA FISCAL DE SERVIÇO\n`,
        `==================================================\n`,
        `NFS-e ID: ${result.nfe_id}\n`,
        `Prestador: Vextron Lab - Soluções em Automação\n`,
        `Tomador: ${selectedFaturasCompany.nome}\n`,
        `Vencimento da Fatura: ${fatura.data_vencimento}\n`,
        `Valor Pago: R$ ${parseFloat(fatura.valor_mensalidade || 0).toFixed(2)}\n`,
        `Status: PAGO\n`,
        `Data de Emissão: ${new Date().toLocaleDateString('pt-BR')}\n`,
        `==================================================\n`,
        `Este é um recibo fiscal auxiliar simulado para o Zênite OS.\n`
      ], { type: 'text/plain;charset=utf-8' });
      element.href = URL.createObjectURL(file);
      element.download = `NFS-e_${result.nfe_id}_${selectedFaturasCompany.nome.replace(/\s+/g, '_')}.txt`;
      document.body.appendChild(element);
      element.click();
      document.body.removeChild(element);

    } catch (err) {
      console.error('Erro ao emitir NF', err);
      alert('Falha ao comunicar com o serviço fiscal.');
    } finally {
      setIsFiscalLoading(false);
    }
  };

  const fetchFiscalConfig = async (tenantId) => {
    if (!tenantId || tenantId === 'MASTER') return;
    setIsLoadingFiscalConfig(true);
    try {
      const { data: { session: currentSession } } = await supabase.auth.getSession();
      const token = currentSession?.access_token;
      if (!token) return;

      const res = await safeFetchJson(`/api/fiscal/configuracoes?tenant_id=${tenantId}`, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });
      if (res.ok && res.data?.success && res.data?.config) {
        const config = res.data.config;
        setFiscalCnpj(config.cnpj || '');
        setFiscalInscricaoEstadual(config.inscricao_estadual || '');
        setFiscalInscricaoMunicipal(config.inscricao_municipal || '');
        setFiscalRegimeTributario(config.regime_tributario || 'Simples Nacional');
        setFiscalCertificadoA1Url(config.certificado_a1_url || '');
        setFiscalCertificadoSenha(config.certificado_senha ? '••••••••' : '');
      } else {
        setFiscalCnpj('');
        setFiscalInscricaoEstadual('');
        setFiscalInscricaoMunicipal('');
        setFiscalRegimeTributario('Simples Nacional');
        setFiscalCertificadoA1Url('');
        setFiscalCertificadoSenha('');
      }
    } catch (err) {
      console.error('Erro ao buscar configurações fiscais:', err);
    } finally {
      setIsLoadingFiscalConfig(false);
    }
  };

  const handleSaveFiscalConfig = async (e) => {
    e.preventDefault();
    if (!company?.id) return;
    setIsSavingFiscalConfig(true);
    try {
      const { data: { session: currentSession } } = await supabase.auth.getSession();
      const token = currentSession?.access_token;
      if (!token) {
        alert('Erro: Sessão não encontrada.');
        return;
      }

      const payload = {
        tenant_id: company.id,
        cnpj: fiscalCnpj,
        inscricao_estadual: fiscalInscricaoEstadual,
        inscricao_municipal: fiscalInscricaoMunicipal,
        regime_tributario: fiscalRegimeTributario,
        certificado_a1_url: fiscalCertificadoA1Url
      };

      if (fiscalCertificadoSenha && fiscalCertificadoSenha !== '••••••••') {
        payload.certificado_senha = fiscalCertificadoSenha;
      }

      const { ok, data, error: fetchErr } = await safeFetchJson('/api/fiscal/configuracoes', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(payload)
      });

      if (!ok || !data) {
        throw new Error(fetchErr || 'Falha ao salvar configurações fiscais.');
      }

      alert('Configurações fiscais salvas com sucesso!');
    } catch (err) {
      console.error('Erro ao salvar configurações fiscais:', err);
      alert('Erro: ' + err.message);
    } finally {
      setIsSavingFiscalConfig(false);
    }
  };

  const handleUploadCertificado = async (file) => {
    if (!file) return;
    if (!company?.id) {
      alert('Erro: Empresa não identificada.');
      return;
    }

    // Validar extensão
    const ext = file.name.split('.').pop().toLowerCase();
    if (ext !== 'pfx' && ext !== 'p12') {
      alert('Por favor, envie apenas arquivos com extensão .pfx ou .p12');
      return;
    }

    setCertificadoUploadLoading(true);
    try {
      const folder = company.id;
      // Nome do arquivo com caracteres especiais limpos
      const filename = `${Date.now()}_${file.name.replace(/[^a-zA-Z0-9.-]/g, '_')}`;
      const filePath = `${folder}/${filename}`;

      // Upload do arquivo para o bucket privado 'fiscal-certificates'
      const { data, error } = await supabase.storage
        .from('fiscal-certificates')
        .upload(filePath, file, {
          cacheControl: '3600',
          upsert: true
        });

      if (error) throw error;

      // Armazena o path interno no estado
      setFiscalCertificadoA1Url(filePath);
      alert('Certificado enviado com sucesso!');
    } catch (err) {
      console.error('Erro no upload do certificado:', err);
      alert('Erro ao enviar certificado: ' + err.message);
    } finally {
      setCertificadoUploadLoading(false);
    }
  };

  const handleEmitirNfePdv = async (reciboDados) => {
    if (!hasFeature(company, 'emitir_nfe') && profile?.role !== 'SUPER_ADMIN') {
      alert('Recurso Indisponível: O plano atual da sua empresa (START/PRO) não possui suporte para Emissão de NF-e. Faça um upgrade para o plano ULTIMATE para utilizar esta funcionalidade.');
      return;
    }
    setIsFiscalLoading(true);
    try {
      const { data: { session: currentSession } } = await supabase.auth.getSession();
      const token = currentSession?.access_token;
      if (!token) {
        alert('Erro: Sessão não encontrada. Por favor, faça login novamente.');
        return;
      }

      const { ok, data, error: fetchErr } = await safeFetchJson('/api/fiscal/emitir-nfe-pdv', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          venda_id: reciboDados.venda_id,
          cliente_cpf_cnpj: reciboDados.cliente_cpf_cnpj,
          cliente_nome: reciboDados.cliente_nome,
          cliente_email: reciboDados.cliente_email
        })
      });

      if (!ok || !data) {
        throw new Error(fetchErr || 'Falha ao emitir nota fiscal.');
      }

      alert(`NF-e emitida com sucesso!\nChave: ${data.nfe_id}`);

      setPdvReciboDados(prev => ({
        ...prev,
        nfe_id: data.nfe_id,
        nfe_pdf_url: data.nfe_pdf_url,
        nfe_status: 'EMITIDA'
      }));

      if (data.nfe_pdf_url) {
        window.open(data.nfe_pdf_url, '_blank');
      }

    } catch (err) {
      console.error('Erro ao emitir NF-e:', err);
      alert('Falha na Emissão: ' + err.message);
    } finally {
      setIsFiscalLoading(false);
    }
  };

  useEffect(() => {
    if (company?.id && company.id !== 'MASTER') {
      fetchFiscalConfig(company.id);
    }
  }, [company?.id]);

  const fetchFiliais = async (empresaId) => {
    try {
      let data = null;
      if (empresaId) {
        const { data: empData } = await supabase
          .from('filiais')
          .select('*')
          .eq('empresa_id', empresaId)
          .order('created_at', { ascending: true });
        data = empData;
      }

      // Contingência: carregar todas as filiais caso a busca com filtro não retorne dados
      if (!data || data.length === 0) {
        const { data: allData } = await supabase
          .from('filiais')
          .select('*')
          .order('created_at', { ascending: true });
        data = allData || [];
      }

      setFiliais(data || []);
      if (data && data.length > 0) {
        setFilialVendedor(data[0].id);
        setFilialProduto(data[0].id);
        setFiltroFilialEstoque(data[0].id);
        const estoques = data.filter(f => f.tipo === 'ESTOQUE');
        setEntradaFilial(estoques.length > 0 ? estoques[0].id : '');
      }
      return data || [];
    } catch (err) {
      console.error('Erro ao buscar filiais:', err);
      return [];
    }
  };

  const fetchVendedores = async (empresaId) => {
    try {
      let query = supabase
        .from('profiles')
        .select('*');

      if (empresaId) {
        query = query.eq('empresa_id', empresaId);
      }

      let { data, error } = await query;

      if (error || !data || data.length === 0) {
        const retryRes = await supabase.from('profiles').select('*');
        data = retryRes.data || [];
      }

      // Filtrar para trazer todos os perfis operacionais de linha de frente (Vendedor, Trainee, Treener)
      const rolesOperacionais = ['VENDEDOR', 'TRAINEE', 'TREENER'];
      const vendedoresFiltrados = (data || []).filter(p =>
        rolesOperacionais.includes((p.role || '').toUpperCase()) ||
        rolesOperacionais.includes((p.cargo || '').toUpperCase())
      );

      setVendedores(vendedoresFiltrados.length > 0 ? vendedoresFiltrados : (data || []));

      // Buscar metas do mês atual
      const dataAtual = new Date();
      const mesRef = `${dataAtual.getFullYear()}-${String(dataAtual.getMonth() + 1).padStart(2, '0')}`;
      const { data: metasData, error: metasError } = await supabase
        .from('metas')
        .select('*')
        .eq('tenant_id', empresaId)
        .eq('mes_referencia', mesRef);

      if (!metasError) {
        setMetas(metasData || []);
        // Popular o mapa de tipos para inicializar os dropdowns do gerente
        const tipoMap = {};
        (metasData || []).forEach(m => {
          tipoMap[m.vendedor_id] = m.tipo_meta || 'faturamento';
        });
        setMetaTipoMap(tipoMap);
      }
    } catch (err) {
      console.error('Erro ao buscar vendedores/metas:', err);
    }
  };

  const handleSignOut = async () => {
    localStorage.removeItem('zenite_active_filial_id');
    localStorage.removeItem('zenite_active_filial_nome');
    await supabase.auth.signOut();
  };

  // Cadastro de Filiais (Gerente / Admin)
  const handleAddFilial = async (e) => {
    if (e) e.preventDefault();

    if (!nomeFilial.trim() || !cnpjFilial.trim() || !telefoneFilial.trim() || !enderecoFilial.trim()) {
      showToast('Por favor, preencha todos os campos obrigatórios (Nome, CNPJ, Telefone e Endereço).', 'error');
      return;
    }

    if (!logoFilialFile) {
      showToast('Atenção: O envio da logo da filial é obrigatório.', 'error');
      return;
    }

    setLoadingFilial(true);
    try {
      // 1. Obter e validar o ID da empresa ativa (ou busca no Supabase como fallback)
      let targetEmpresaId = profile?.empresa_id || company?.id || activeEmpresaId;

      let isUUID = typeof targetEmpresaId === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(targetEmpresaId);

      // Se o contexto não tiver um ID de empresa válido, busca no Supabase como fallback
      if (!isUUID) {
        const { data: empData } = await supabase
          .from('companies')
          .select('id')
          .limit(1)
          .maybeSingle();

        if (empData?.id) {
          targetEmpresaId = empData.id;
        } else {
          const { data: empFallback } = await supabase
            .from('empresas')
            .select('id')
            .limit(1)
            .maybeSingle();
          if (empFallback?.id) {
            targetEmpresaId = empFallback.id;
          }
        }
        isUUID = typeof targetEmpresaId === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(targetEmpresaId);
      }

      // Se ainda assim não houver empresa cadastrada no banco, auto-gerar a empresa inicial no Supabase
      if (!isUUID) {
        const defaultCompanyId = '00000000-0000-0000-0000-000000000001';
        const { data: createdCompany } = await supabase.from('companies').upsert({
          id: defaultCompanyId,
          nome: 'Rede Cred',
          nome_fantasia: 'Rede Cred',
          status: 'ATIVO'
        }).select('id').maybeSingle();

        if (createdCompany?.id) {
          targetEmpresaId = createdCompany.id;
        } else {
          targetEmpresaId = defaultCompanyId;
        }
        isUUID = typeof targetEmpresaId === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(targetEmpresaId);
      }

      if (!targetEmpresaId || !isUUID) {
        showToast('Erro: Nenhuma empresa encontrada para vincular a filial.', 'error');
        setLoadingFilial(false);
        return;
      }

      // Se estiver editando uma filial existente
      if (editingFilial) {
        let logoUrl = editingFilial.logo_url || null;
        if (logoFilialFile) {
          const fileExt = logoFilialFile.name.split('.').pop();
          const fileName = `${targetEmpresaId}/${Date.now()}.${fileExt}`;
          const { error: uploadErr } = await supabase.storage.from('logos_filiais').upload(fileName, logoFilialFile);
          if (!uploadErr) {
            const { data: pubUrlData } = supabase.storage.from('logos_filiais').getPublicUrl(fileName);
            logoUrl = pubUrlData.publicUrl;
          }
        }

        const updatePayload = {
          nome: nomeFilial.trim(),
          tipo: tipoFilial || 'LOJA',
          cnpj: cnpjFilial.trim(),
          telefone: telefoneFilial.trim(),
          endereco: enderecoFilial.trim(),
          logo_url: logoUrl
        };

        let { data: updatedData, error: updateErr } = await supabase
          .from('filiais')
          .update(updatePayload)
          .eq('id', editingFilial.id)
          .select()
          .single();

        if (updateErr) {
          showToast('Erro ao atualizar filial: ' + updateErr.message, 'error');
          return;
        }

        setFiliais(prev => prev.map(f => f.id === editingFilial.id ? (updatedData || { ...f, ...updatePayload }) : f));
        handleCancelEditFilial();
        showToast('Filial atualizada com sucesso!', 'success');
        return;
      }

      // 2. Upload da Logo se informada
      let logoUrl = null;
      if (logoFilialFile) {
        const fileExt = logoFilialFile.name.split('.').pop();
        const fileName = `${targetEmpresaId}/${Date.now()}.${fileExt}`;
        const { error: uploadErr } = await supabase.storage.from('logos_filiais').upload(fileName, logoFilialFile);

        if (uploadErr) {
          console.warn('Aviso ao fazer upload do logo:', uploadErr);
          showToast('Aviso: Houve um erro ao enviar a logo, cadastrando sem a imagem.', 'info');
        } else {
          const { data: pubUrlData } = supabase.storage.from('logos_filiais').getPublicUrl(fileName);
          logoUrl = pubUrlData.publicUrl;
        }
      }

      // 3. Executar o Insert garantindo o ID válido de empresa_id
      const filialPayload = {
        nome: nomeFilial.trim(),
        tipo: tipoFilial || 'LOJA',
        empresa_id: targetEmpresaId,
        cnpj: cnpjFilial.trim(),
        telefone: telefoneFilial.trim(),
        endereco: enderecoFilial.trim(),
        logo_url: logoUrl
      };

      const { data, error } = await supabase
        .from('filiais')
        .insert(filialPayload)
        .select()
        .single();

      if (error) {
        console.error('Erro ao cadastrar filial no Supabase:', error);

        const isFkError = error.code === '23503' || (
          error.message && (
            error.message.includes('filiais_empresa_id_fkey') ||
            error.message.includes('foreign key constraint') ||
            error.message.includes('23503')
          )
        );

        if (isFkError) {
          showToast('Erro: Nenhuma empresa encontrada para vincular a filial.', 'error');
          return;
        }

        const isRlsError = error.code === '42501' || (
          error.message && (
            error.message.includes('row-level security') ||
            error.message.includes('violates row-level security policy')
          )
        );

        if (isRlsError) {
          showToast('Permissão Insuficiente (RLS): Você não tem permissão para cadastrar novas filiais. É necessário ter nível de acesso de Administrador ou Dono da empresa.', 'error');
          return;
        }

        showToast('Erro ao cadastrar filial: ' + (error.message || 'Verifique as informações.'), 'error');
        return;
      }

      if (data) {
        setFiliais(prev => [...prev, data]);
      }
      handleCancelEditFilial();
      showToast('Filial cadastrada com sucesso!', 'success');

    } catch (err) {
      console.error('Erro inesperado ao adicionar filial:', err);
      showToast('Erro ao processar cadastro da filial: ' + (err.message || ''), 'error');
    } finally {
      setLoadingFilial(false);
    }
  };

  const handleStartEditFilial = (f) => {
    setEditingFilial(f);
    setNomeFilial(f.nome || '');
    setTipoFilial(f.tipo || (f.is_deposito ? 'ESTOQUE' : 'LOJA'));
    setCnpjFilial(f.cnpj || '');
    setTelefoneFilial(f.telefone || '');
    setEnderecoFilial(f.endereco || '');
    setLogoFilialFile(null);
    const element = document.getElementById('filial-form-container');
    if (element) element.scrollIntoView({ behavior: 'smooth' });
  };

  const handleCancelEditFilial = () => {
    setEditingFilial(null);
    setNomeFilial('');
    setTipoFilial('LOJA');
    setCnpjFilial('');
    setTelefoneFilial('');
    setEnderecoFilial('');
    setLogoFilialFile(null);
  };

  const handleDeleteFilial = async (filialId) => {
    if (!window.confirm("ATENÇÃO! Excluir esta filial removerá ela do sistema. Tem certeza absoluta que deseja excluir?")) return;
    try {
      const { error } = await supabase.from('filiais').delete().eq('id', filialId);
      if (error) throw error;
      setFiliais(prev => prev.filter(f => f.id !== filialId));
      alert("Filial excluída com sucesso.");
    } catch (err) {
      alert("Erro ao excluir filial: " + err.message);
    }
  };

  const handleEstornarVenda = async (vendaId) => {
    if (!window.confirm("ATENÇÃO! Tem certeza que deseja estornar (apagar) esta venda do histórico financeiro?")) return;
    try {
      const { error } = await supabase.from('vendas').delete().eq('id', vendaId);
      if (error) throw error;
      setVendas(prev => prev.filter(v => v.id !== vendaId));
      alert("Venda estornada com sucesso.");
    } catch (err) {
      alert("Erro ao estornar venda: " + err.message);
    }
  };

  const handleConfirmarBaixaPagamento = async (e) => {
    if (e) e.preventDefault();
    if (!modalBaixaVenda) return;
    const valBaixaNum = parseFloat(baixaValor);
    if (!valBaixaNum || valBaixaNum <= 0) {
      alert("Por favor, informe um valor de pagamento válido maior que zero.");
      return;
    }

    const valorTotalVenda = parseFloat(modalBaixaVenda.valor_total || 0);
    const valorJaPago = parseFloat(modalBaixaVenda.valor_pago || 0);
    const saldoDevedor = Math.max(0, valorTotalVenda - valorJaPago);

    if (valBaixaNum > saldoDevedor + 0.01) {
      alert(`O valor informado (R$ ${valBaixaNum.toFixed(2)}) é maior que o saldo devedor restante (R$ ${saldoDevedor.toFixed(2)}).`);
      return;
    }

    setLoadingBaixa(true);
    try {
      const targetEmpresaId = profile?.empresa_id || company?.id || activeEmpresaId;
      // 1. Inserir pagamento na tabela vendas_pagamentos
      const { error: insertErr } = await supabase.from('vendas_pagamentos').insert({
        venda_id: modalBaixaVenda.id,
        valor_pago: valBaixaNum,
        metodo_pagamento: baixaMetodo,
        tenant_id: targetEmpresaId
      });
      if (insertErr) throw insertErr;

      // 2. Calcular novo total pago e novo status
      const novoValorPagoTotal = valorJaPago + valBaixaNum;
      const novoStatus = (novoValorPagoTotal >= valorTotalVenda - 0.01) ? 'PAGO' : 'PARCIAL';

      // 3. Atualizar tabela vendas
      const { error: updateErr } = await supabase.from('vendas').update({
        valor_pago: novoValorPagoTotal,
        status_pagamento: novoStatus
      }).eq('id', modalBaixaVenda.id);

      if (updateErr) throw updateErr;

      // 4. Atualizar estado local de vendas
      setVendas(prev => prev.map(v => {
        if (v.id === modalBaixaVenda.id) {
          return { ...v, valor_pago: novoValorPagoTotal, status_pagamento: novoStatus };
        }
        return v;
      }));

      showToast(`Pagamento de R$ ${valBaixaNum.toFixed(2)} registrado com sucesso!`, 'success');
      setModalBaixaVenda(null);
      setBaixaValor('');
    } catch (err) {
      console.error("Erro ao registrar baixa de pagamento:", err);
      alert("Erro ao registrar pagamento: " + (err.message || 'Tente novamente.'));
    } finally {
      setLoadingBaixa(false);
    }
  };

  // Cadastro de Vendedores (Gerente / RH)
  const handleAddVendedor = async (e) => {
    if (e) e.preventDefault();
    const currentEmpresaId = profile?.empresa_id || company?.id || activeEmpresaId;

    if (!currentEmpresaId) {
      showToast('Acesso Restrito: O seu utilizador de RH não está vinculado a nenhuma empresa.', 'error');
      return;
    }

    if (!nomeVendedor.trim() || !emailVendedor.trim() || !senhaVendedor.trim() || !filialVendedor) {
      showToast('Por favor, preencha todos os campos do vendedor.', 'error');
      return;
    }

    setLoadingVendedor(true);
    try {
      // 1. Criar o usuário no Supabase Auth usando o cliente de registro público (sem persistir sessão)
      const { data: authData, error: authError } = await supabaseRegister.auth.signUp({
        email: emailVendedor.trim(),
        password: senhaVendedor.trim(),
        options: {
          data: {
            nome_completo: nomeVendedor.trim(),
            role: 'VENDEDOR',
            empresa_id: currentEmpresaId,
            filial_id: filialVendedor
          }
        }
      });

      if (authError) {
        if (authError.message?.toLowerCase().includes('already registered')) {
          const { data: existingProfile } = await supabase
            .from('profiles')
            .select('*')
            .ilike('email', emailVendedor.trim())
            .maybeSingle();

          if (existingProfile) {
            await supabase
              .from('profiles')
              .update({
                empresa_id: currentEmpresaId,
                filial_id: filialVendedor,
                nome: nomeVendedor.trim(),
                role: 'VENDEDOR'
              })
              .eq('id', existingProfile.id);

            showToast(`O e-mail (${emailVendedor.trim()}) já possuía cadastro e foi vinculado com sucesso a esta filial!`, 'info');
          } else {
            showToast(`Aviso: O e-mail (${emailVendedor.trim()}) já possui cadastro no Auth.`, 'info');
          }
        } else {
          showToast(`Erro ao criar vendedor: ${authError.message}`, 'error');
          return;
        }
      } else if (authData?.user?.id) {
        await new Promise(resolve => setTimeout(resolve, 500));
        await supabase
          .from('profiles')
          .upsert({
            id: authData.user.id,
            empresa_id: currentEmpresaId,
            filial_id: filialVendedor,
            nome: nomeVendedor.trim(),
            email: emailVendedor.trim(),
            role: 'VENDEDOR'
          });
      }

      showToast(`Funcionário / Vendedor "${nomeVendedor.trim()}" cadastrado com sucesso!`, 'success');

      setNomeVendedor('');
      setEmailVendedor('');
      setSenhaVendedor('');
      fetchTeamMembers(company.id);
    } catch (err) {
      console.error('Erro ao cadastrar vendedor:', err);
      alert('Erro ao cadastrar vendedor: ' + err.message);
    } finally {
      setLoadingVendedor(false);
    }
  };

  // Alternar Status de Trainee de um Vendedor (Gerente)
  const handleUpdateMeta = async (vendedorId, rawMeta, tipoMeta = 'faturamento') => {
    try {
      // 0. AUDITORIA DE SESSÃO ESTREITA (Poka-Yoke)
      const { data: { session }, error: sessionError } = await supabase.auth.getSession();

      if (sessionError || !session) {
        console.error("Erro de Autenticação ao salvar meta:", sessionError);
        alert("Sua sessão expirou ou não foi validada. Recarregue a página e faça login novamente.");
        return; // BLOQUEIA A EXECUÇÃO AQUI. Não tenta bater no banco.
      }

      const sanitized = String(rawMeta).replace(/[^\d.,]/g, '').replace(',', '.');
      const novaMeta = parseFloat(sanitized);

      if (isNaN(novaMeta)) {
        alert('Por favor, digite um valor numérico válido.');
        return;
      }
      const dataAtual = new Date();
      const mesRef = `${dataAtual.getFullYear()}-${String(dataAtual.getMonth() + 1).padStart(2, '0')}`;

      // Garantir sanitização e tipo_meta válido (minúsculas ou fallback)
      let validTipoMeta = String(tipoMeta || 'faturamento').toLowerCase().trim();
      if (!['faturamento', 'quantidade', 'ativacao'].includes(validTipoMeta)) {
        if (validTipoMeta.includes('faturamento') || validTipoMeta.includes('geral')) validTipoMeta = 'faturamento';
        else if (validTipoMeta.includes('boleto') || validTipoMeta.includes('qtd')) validTipoMeta = 'quantidade';
        else if (validTipoMeta.includes('ativa')) validTipoMeta = 'ativacao';
        else validTipoMeta = 'faturamento';
      }

      // 1. Resolução segura do Tenant ID (Poka-Yoke)
      let targetTenantId = company?.id || profile?.empresa_id || activeEmpresaId;

      // Se for sintético ou inválido, buscar da conta do próprio vendedor
      if (!targetTenantId || targetTenantId === 'MASTER' || targetTenantId === '00000000-0000-0000-0000-000000000001') {
        const { data: vProfile } = await supabase.from('profiles').select('empresa_id').eq('id', vendedorId).maybeSingle();
        if (vProfile?.empresa_id && vProfile.empresa_id !== 'MASTER' && vProfile.empresa_id !== '00000000-0000-0000-0000-000000000001') {
          targetTenantId = vProfile.empresa_id;
        }
      }

      // Se ainda for inválido, buscar a primeira empresa cadastrada no banco
      if (!targetTenantId || targetTenantId === 'MASTER' || targetTenantId === '00000000-0000-0000-0000-000000000001') {
        const { data: empList } = await supabase.from('companies').select('id').limit(1);
        if (empList && empList.length > 0) {
          targetTenantId = empList[0].id;
        } else {
          const { data: empListAlt } = await supabase.from('empresas').select('id').limit(1);
          if (empListAlt && empListAlt.length > 0) {
            targetTenantId = empListAlt[0].id;
          }
        }
      }

      // Trava de segurança (Poka-Yoke) ANTES de chamar o Supabase
      if (!targetTenantId || targetTenantId === 'MASTER' || targetTenantId === '00000000-0000-0000-0000-000000000001') {
        alert('Erro interno: ID da empresa não identificado na sessão. Por favor, recarregue a página.');
        return;
      }

      console.log('Enviando payload de meta para o Supabase:', {
        vendedor_id: vendedorId,
        tenant_id: targetTenantId,
        valor_meta: novaMeta,
        tipo_meta: validTipoMeta,
        mes_referencia: mesRef
      });

      // Upsert logic (checking if exists first since Supabase UPSERT might require unique constraints we want to handle safely here)
      const { data: existing } = await supabase
        .from('metas')
        .select('id')
        .eq('vendedor_id', vendedorId)
        .eq('mes_referencia', mesRef)
        .maybeSingle();

      let dbError = null;

      if (existing) {
        const { error } = await supabase
          .from('metas')
          .update({ valor_meta: novaMeta, tipo_meta: validTipoMeta })
          .eq('id', existing.id);
        dbError = error;
      } else {
        const insertPayload = {
          vendedor_id: vendedorId,
          tenant_id: targetTenantId,
          valor_meta: novaMeta,
          tipo_meta: validTipoMeta,
          mes_referencia: mesRef
        };
        const { error } = await supabase
          .from('metas')
          .insert(insertPayload);
        dbError = error;
      }

      // Se houver erro de CHECK CONSTRAINT "metas_tipo_meta_check", tentar fallback com os tipos em maiúsculas ('FATURAMENTO_GERAL' / 'BOLETO')
      if (dbError && (dbError.message?.includes('metas_tipo_meta_check') || dbError.details?.includes('metas_tipo_meta_check') || dbError.code === '23514')) {
        console.warn('Detectado erro no CHECK CONSTRAINT metas_tipo_meta_check. Tentando fallback para tipos maiúsculos:', dbError.message);
        let fallbackTipo = 'FATURAMENTO_GERAL';
        if (validTipoMeta === 'quantidade') fallbackTipo = 'BOLETO';
        if (validTipoMeta === 'ativacao') fallbackTipo = 'BOLETO';

        if (existing) {
          const { error: retryErr } = await supabase
            .from('metas')
            .update({ valor_meta: novaMeta, tipo_meta: fallbackTipo })
            .eq('id', existing.id);
          dbError = retryErr;
        } else {
          const fallbackPayload = {
            vendedor_id: vendedorId,
            tenant_id: targetTenantId,
            valor_meta: novaMeta,
            tipo_meta: fallbackTipo,
            mes_referencia: mesRef
          };
          const { error: retryErr } = await supabase
            .from('metas')
            .insert(fallbackPayload);
          dbError = retryErr;
        }
      }

      if (dbError) throw dbError;

      // Update local state (valor + tipo)
      setMetas(prev => {
        const idx = prev.findIndex(m => m.vendedor_id === vendedorId && m.mes_referencia === mesRef);
        if (idx >= 0) {
          const arr = [...prev];
          arr[idx] = { ...arr[idx], valor_meta: novaMeta, tipo_meta: validTipoMeta };
          return arr;
        }
        return [...prev, { vendedor_id: vendedorId, mes_referencia: mesRef, valor_meta: novaMeta, tipo_meta: validTipoMeta }];
      });
      setMetaTipoMap(prev => ({ ...prev, [vendedorId]: validTipoMeta }));
      alert('Meta atualizada com sucesso!');
    } catch (err) {
      console.error('Erro ao atualizar meta (detalhado):', err);
      alert(`Falha ao atualizar meta. Motivo: ${err.message || JSON.stringify(err)}`);
    }
  };

  const handleDeleteVendedor = async (vendedorId, vendedorNome) => {
    if (!window.confirm(`Tem certeza que deseja EXCLUIR DEFINITIVAMENTE o vendedor "${vendedorNome}"? Isso apagará o acesso dele ao sistema.`)) {
      return;
    }

    setLoadingVendedor(true);
    try {
      const { error } = await supabase
        .from('profiles')
        .delete()
        .eq('id', vendedorId);

      if (error) throw error;

      setVendedores(prev => prev.filter(v => v.id !== vendedorId));
      alert('Vendedor removido com sucesso!');
    } catch (err) {
      console.error('Erro ao excluir vendedor:', err);
      alert('Falha ao excluir vendedor.');
    } finally {
      setLoadingVendedor(false);
    }
  };

  const handleUpdateProdutoField = async (produtoId, nome, field, newValue, itemFilialId) => {
    const targetEmpresaId = profile?.empresa_id || company?.id || activeEmpresaId;
    const resolvedFilialId = itemFilialId || activeFilialId || filiais[0]?.id;

    if (field === 'cor') {
      const corTrimmed = String(newValue || '').trim();
      try {
        if (produtoId && !String(produtoId).startsWith('synth_')) {
          let q = supabase.from('produtos').update({ cor: corTrimmed }).eq('id', produtoId);
          if (resolvedFilialId) {
            q = q.eq('filial_id', resolvedFilialId);
          }
          const { error } = await q;
          if (error) throw error;
        }

        // Optimistic UI updates (isolado estritamente por produto e filial)
        setProdutos(prev => prev.map(p => (p.id === produtoId || (p.nome === nome && (!resolvedFilialId || p.filial_id === resolvedFilialId))) ? { ...p, cor: corTrimmed } : p));
        setProdutosFilial(prev => prev.map(p => (p.id === produtoId || (p.nome === nome && (!resolvedFilialId || p.filial_id === resolvedFilialId))) ? { ...p, cor: corTrimmed } : p));
        setCatalogoProdutos(prev => prev.map(c => (c.id === produtoId || c.nome === nome) ? { ...c, cor: corTrimmed } : c));
        showToast(`Cor de "${nome}" alterada para "${corTrimmed || 'Sem cor'}" com sucesso!`, 'success');
      } catch (err) {
        console.error('Erro ao atualizar cor:', err);
        showToast('Erro ao atualizar cor: ' + err.message, 'error');
      }
    } else if (field === 'preco') {
      const sanitized = String(newValue).replace(/[^\d.,]/g, '').replace(',', '.');
      const novoPreco = parseFloat(sanitized);

      if (isNaN(novoPreco) || novoPreco < 0) {
        showToast('Por favor, informe um preço numérico válido.', 'error');
        return;
      }

      try {
        if (produtoId && !String(produtoId).startsWith('synth_')) {
          let q = supabase.from('produtos').update({ preco: novoPreco }).eq('id', produtoId);
          if (resolvedFilialId) {
            q = q.eq('filial_id', resolvedFilialId);
          }
          const { error } = await q;
          if (error) throw error;
        }

        // Optimistic UI updates (isolado estritamente por produto e filial)
        setProdutos(prev => prev.map(p => (p.id === produtoId || (p.nome === nome && (!resolvedFilialId || p.filial_id === resolvedFilialId))) ? { ...p, preco: novoPreco } : p));
        setProdutosFilial(prev => prev.map(p => (p.id === produtoId || (p.nome === nome && (!resolvedFilialId || p.filial_id === resolvedFilialId))) ? { ...p, preco: novoPreco } : p));
        setCatalogoProdutos(prev => prev.map(c => (c.id === produtoId || c.nome === nome) ? { ...c, preco: novoPreco } : c));
        showToast(`Preço de "${nome}" atualizado para R$ ${novoPreco.toFixed(2)} com sucesso!`, 'success');
      } catch (err) {
        console.error('Erro ao atualizar preço:', err);
        showToast('Erro ao atualizar preço: ' + err.message, 'error');
      }
    } else if (field === 'quantidade') {
      const novaQtd = parseInt(newValue, 10);
      if (isNaN(novaQtd) || novaQtd < 0) {
        showToast('Por favor, informe uma quantidade inteira válida (>= 0).', 'error');
        return;
      }

      try {
        if (produtoId && !String(produtoId).startsWith('synth_')) {
          // ISOLAMENTO TOTAL (PATCH): Atualiza APENAS { quantidade: novaQtd } com chave composta .eq('id', produtoId).eq('filial_id', resolvedFilialId)
          let q = supabase.from('produtos').update({ quantidade: novaQtd }).eq('id', produtoId);
          if (resolvedFilialId) {
            q = q.eq('filial_id', resolvedFilialId);
          }
          const { error } = await q;
          if (error) throw error;
        } else if (nome && resolvedFilialId) {
          // Produto sintético: buscar exclusivamente na filial da linha
          const { data: prodsBanco } = await supabase
            .from('produtos')
            .select('id, filial_id')
            .eq('empresa_id', targetEmpresaId)
            .eq('filial_id', resolvedFilialId)
            .ilike('nome', nome);

          if (prodsBanco && prodsBanco.length > 0) {
            const { error: updErr } = await supabase
              .from('produtos')
              .update({ quantidade: novaQtd })
              .eq('id', prodsBanco[0].id)
              .eq('filial_id', resolvedFilialId);
            if (updErr) throw updErr;
          } else {
            const catMatch = (catalogoProdutos || []).find(c => c.nome?.toLowerCase() === nome.toLowerCase()) || {};
            const { error: insErr } = await supabase
              .from('produtos')
              .insert({
                empresa_id: targetEmpresaId,
                filial_id: resolvedFilialId,
                nome: nome,
                tipo: catMatch.tipo || 'ACESSORIO',
                categoria: catMatch.categoria || 'GERAL',
                preco: parseFloat(catMatch.preco || 0),
                quantidade: novaQtd,
                sku: catMatch.sku || null,
                codigo_barras: catMatch.codigo_barras || null
              });
            if (insErr) throw insErr;
          }
        }

        // Optimistic UI updates
        setProdutos(prev => prev.map(p => (p.id === produtoId || (p.nome?.toLowerCase() === nome?.toLowerCase() && p.filial_id === resolvedFilialId)) ? { ...p, quantidade: novaQtd } : p));
        setProdutosFilial(prev => prev.map(p => (p.id === produtoId || (p.nome?.toLowerCase() === nome?.toLowerCase() && p.filial_id === resolvedFilialId)) ? { ...p, quantidade: novaQtd } : p));

        showToast(`Estoque de "${nome}" alterado para ${novaQtd} un. com sucesso!`, 'success');

        const filialParaRecarregar = filtroFilialEstoque || resolvedFilialId || activeFilialId;
        if (filialParaRecarregar) {
          await fetchEstoqueConsolidado(filialParaRecarregar, buscaEstoque, filtroCategoriaEstoque);
        }
      } catch (err) {
        console.error('Erro ao atualizar quantidade:', err);
        showToast('Erro ao atualizar estoque: ' + err.message, 'error');
      }
    }
  };

  const handleUpdateProdutoPreco = async (produtoId, nome, precoAtual, itemFilialId) => {
    const novoPrecoStr = window.prompt(`Novo preço para ${nome}:`, precoAtual);
    if (novoPrecoStr === null) return; // User cancelled

    const sanitized = String(novoPrecoStr).replace(/[^\d.,]/g, '').replace(',', '.');
    const novoPreco = parseFloat(sanitized);

    if (isNaN(novoPreco)) {
      showToast('Por favor, digite um preço numérico válido.', 'error');
      return;
    }

    try {
      const resolvedFilialId = itemFilialId || activeFilialId || filiais[0]?.id;

      // 1. Atualizar com payload estritamente isolado { preco: novoPreco } e chave composta
      if (produtoId && !String(produtoId).startsWith('synth_')) {
        let q = supabase.from('produtos').update({ preco: novoPreco }).eq('id', produtoId);
        if (resolvedFilialId) {
          q = q.eq('filial_id', resolvedFilialId);
        }
        const { error } = await q;
        if (error) throw error;
      }

      // 2. Atualizar estados locais apenas para o item na filial correta
      setProdutos(prev => prev.map(p => (p.id === produtoId || (p.nome === nome && (!resolvedFilialId || p.filial_id === resolvedFilialId))) ? { ...p, preco: novoPreco } : p));
      setProdutosFilial(prev => prev.map(p => (p.id === produtoId || (p.nome === nome && (!resolvedFilialId || p.filial_id === resolvedFilialId))) ? { ...p, preco: novoPreco } : p));
      setCatalogoProdutos(prev => prev.map(c => (c.id === produtoId || c.nome === nome) ? { ...c, preco: novoPreco } : c));

      showToast(`Preço de "${nome}" atualizado para R$ ${novoPreco.toFixed(2)} com sucesso!`, 'success');
    } catch (err) {
      console.error('Erro ao atualizar preço:', err);
      showToast('Erro ao atualizar preço: ' + err.message, 'error');
    }
  };

